/** FIX 4.2 ListExecute (35=L). Generated by spec/GeneratorJava.rb. */
public class ListExecute extends Message {
    public static final String MSGTYPE = "L";

    public ListExecute() {
        getHeader().setField(35, MSGTYPE);
    }

    private ListExecute(long cPtr) {
        super(cPtr, false);
    }

    /**
     * message as a ListExecute, without copying it: the same engine object, so valid only while message is. A
     * callback's message is the engine's and lasts only for the callback; copy it (new Message(message)) to keep it.
     */
    public static ListExecute view(com.dudleylane.quickfix.Message message) {
        if (!MSGTYPE.equals(message.getHeader().getField(35))) {
            throw new IllegalArgumentException("not a ListExecute (35=" + MSGTYPE + "): 35=" + message.getHeader().getField(35));
        }
        return new ListExecute(getCPtr(message));
    }
}
